<?php require_once __DIR__.'/../includes/layout.php'; require_once __DIR__.'/../includes/validation.php'; $u=require_login(); $msg=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf(); $s=db()->prepare('SELECT password_hash FROM users WHERE id=?');$s->execute([$u['id']]); $hash=$s->fetchColumn(); $errs=password_errors($_POST['new_password']??''); if(!password_verify($_POST['current_password']??'',$hash))$errs[]='Current password is invalid.'; if($_POST['new_password']!==($_POST['confirm_password']??''))$errs[]='Passwords do not match.'; if(!$errs){db()->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($_POST['new_password'],PASSWORD_DEFAULT),$u['id']]); audit('password_change','users',$u['id']); $msg='Password changed.';} else $msg=implode(' ',$errs);} dashboard_header('Change Password'); ?><div class="glass-card p-4"><p><?=e($msg)?></p><form method="post" class="vstack gap-3"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="password" name="current_password" class="form-control" placeholder="Current"><input type="password" name="new_password" class="form-control" placeholder="New" data-strength="#strength"><div class="progress"><div id="strength" class="progress-bar"></div></div><input type="password" name="confirm_password" class="form-control" placeholder="Confirm"><button class="btn btn-premium">Update</button></form></div><?php dashboard_footer(); ?>
